<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class mgarmentsamplingmodel extends CI_Model {    function fnGetInfo($Varrequirement = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,requirement,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_GARMENT_SAMPLING);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($Varrequirement <> '') {            $ArrWhere['requirement'] = $Varrequirement;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_MASTER_GARMENT_SAMPLING);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['requirement'] = $VarData;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['requirement'], 1);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_GARMENT_SAMPLING, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This requirement already exists";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrUpdateData['requirement'], $VarId);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_GARMENT_SAMPLING, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data!';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This requirement has already exist";            }        }        return $ArrResult;    }    function fnCount($Varrequirement = '', $VarStatus = '', $VarAfilter = '') {        $userInfo = fnGetUserLoggedInfo(1);        $ArrWhere = array();        if ($Varrequirement <> '') {            $ArrWhere[] = "requirement like '%" . $Varrequirement . "%'";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "requirement LIKE '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "gs.status=" . $VarStatus;        } else {            $ArrWhere[] = "gs.status in(1,2)";        }        $ArrWhere[] = "gs.companyid = " . $userInfo['companyid'];        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_GARMENT_SAMPLING . " AS gs INNER JOIN " . KN_USERS . " AS u ON gs.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($Varrequirement = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $userInfo = fnGetUserLoggedInfo(1);        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('requirement', 'gs.status', 'u.contactname', 'gs.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'gs.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($Varrequirement <> '') {            $ArrWhere[] = "gs.requirement like '%" . $Varrequirement . "%'";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "gs.requirement LIKE '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "gs.status=" . $VarStatus;        } else {            $ArrWhere[] = "gs.status in(1,2)";        }        $ArrWhere[] = "gs.companyid = " . $userInfo['companyid'];        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSqlLab = "SELECT gs.id,requirement,u.contactname,gs.dateupdated,gs.status FROM " . KN_MASTER_GARMENT_SAMPLING . " AS gs INNER JOIN " . KN_USERS . " AS u ON gs.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_GARMENT_SAMPLING, array('status' => $optvalue))) {            return true;        }        return false;    }}